class Solution:
    def maximumSum(self, nums: List[int]) -> int:
        groups = defaultdict(int)

        def square_free(x):
            i = 2
            res = 1
            while i * i <= x:
                if x % i == 0:
                    count = 0
                    while x % i == 0:
                        x //= i
                        count += 1
                    if count % 2 == 1:
                        res *= i
                i += 1
            if x > 1:
                res *= x
            return res

        max_sum = 0
        for num in nums:
            sf = square_free(num)
            groups[sf] += num
            max_sum = max(max_sum, groups[sf])

        return max_sum
