    def maximumSum(self, nums: List[int]) -> int:
        def get_square_free(x):
            square_free = 1
            # Handle factor 2
            count = 0
            while x % 2 == 0:
                count += 1
                x //= 2
            if count % 2 == 1:
                square_free *= 2
            # Handle odd factors
            p = 3
            while p * p <= x:
                count_p = 0
                while x % p == 0:
                    count_p += 1
                    x //= p
                if count_p % 2 == 1:
                    square_free *= p
                p += 2
            # If x is a prime left
            if x > 1:
                square_free *= x
            return square_free

        groups = defaultdict(int)
        for num in nums:
            sf = get_square_free(num)
            groups[sf] += num

        return max(groups.values()) if groups else 0
